	/**
	 * Returns whether a Workbench route may be requested. The input may be a route segment such as /query or a complete
	 * application path containing a repository ID.
	 *
	 * @param path request path or route segment
	 * @return true when the canonical page is enabled
	 */
	public boolean isRouteAllowed(String path) {
		String route = normalizeRoute(path);
		if (route.isEmpty() || route.equals("info") || route.equals(INTERNAL_NAMESPACES_PATH.substring(1))) {
			return true;
		}
		String builtInId = BUILT_IN_ROUTE_IDS.get(route);
		if (builtInId != null) {
			return visibleMenuItemsById.containsKey(builtInId) && areCustomAliasesVisible(path);
		}
		List<String> customIds = customRouteIds(path);
		return customIds.isEmpty() || customIds.stream().allMatch(visibleMenuItemsById::containsKey);
	}

	/**
	 * Applies the registered servlet type before route aliases. This prevents a second URL mapping to a built-in
	 * servlet from bypassing that page's visibility policy.
	 *
	 * @param path        request path or route segment
	 * @param servletType concrete registered child servlet type, if known
	 * @return true when the canonical page is enabled
	 */
	public boolean isRouteAllowed(String path, Class<?> servletType) {
		String canonicalId = canonicalPageId(servletType);
		if (canonicalId != null) {
			return visibleMenuItemsById.containsKey(canonicalId) && areCustomAliasesVisible(path);
		}
		return isRouteAllowed(path);
	}

	/**
	 * Selects a visible landing page suitable for the current Workbench context. The configured default is preferred
	 * when it names an enabled page in that context; otherwise a stable built-in fallback order is used.
	 *
	 * @param context       global Workbench or selected-repository context
	 * @param preferredPath configured default path or command
	 * @return the preferred or fallback route, or {@code null} when no page is enabled for the context
	 */
	public String selectLandingPath(LandingContext context, String preferredPath) {
		Objects.requireNonNull(context, "context");
		String preferredPageId = pageIdForPath(preferredPath);
		if (preferredPageId != null && isPageVisibleInContext(preferredPageId, context)
				&& isRouteAllowed(preferredPath)) {
			return preferredPath;
		}
		List<String> candidates = context == LandingContext.WORKBENCH
				? List.of("repositories", "server")
				: List.of("summary", "query", "explore", "namespaces", "contexts", "types", "saved-queries", "export",
						"information", "update", "add", "remove", "clear");
		for (String candidate : candidates) {
			String candidatePath = landingPathFor(candidate);
			if (visibleMenuItemsById.containsKey(candidate) && isRouteAllowed(candidatePath)) {
				return candidatePath;
			}
		}
		return null;
	}

	/** Returns whether a path names one of the Workbench-level built-in landing pages. */
	public boolean isWorkbenchLandingPath(String path) {
		String pageId = pageIdForPath(path);
		return "server".equals(pageId) || "repositories".equals(pageId);
	}

