	private static void validateProperties(Properties values, Set<String> declaredIds, Set<String> knownGroupIds,
			Set<String> featureIds) {
		for (String key : values.stringPropertyNames()) {
			String value = values.getProperty(key);
			if (Set.of(MENU_ITEMS_KEY, MENU_GROUPS_KEY, MENU_CONSUMER_IDS_KEY, QUERY_CONSUMER_FEATURE_IDS_KEY)
					.contains(key)) {
				continue;
			}
			if (QUERY_DOWNLOAD_DEFAULT_LIMIT_KEY.equals(key)) {
				parseInteger(values, key, 0);
				continue;
			}
			if (DEPLOYMENT_THEME_DEFAULT_KEY.equals(key)) {
				String theme = value.trim().toLowerCase(Locale.ROOT);
				if (!Set.of("system", "light", "dark").contains(theme)) {
					throw new IllegalArgumentException(key + " must be system, light, or dark");
				}
				continue;
			}
			if (key.startsWith("menu.item.")) {
				String[] parts = key.substring("menu.item.".length()).split("\\.", 2);
				if (parts.length != 2 || !declaredIds.contains(parts[0])) {
					throw new IllegalArgumentException("Unknown or undeclared Workbench property: " + key);
				}
				switch (parts[1]) {
				case "visible":
					parseBoolean(values, key, true);
					break;
				case "order":
					parseInteger(values, key, 0);
					break;
				case "href":
					validateHref(parts[0], value.trim());
					break;
				case "route":
					if (!value.isBlank()) {
						validateRoute(parts[0], value.trim());
					}
					break;
				case "group":
					validateId(value.trim(), "Workbench menu item group ID");
					if (!knownGroupIds.contains(value.trim())) {
						throw new IllegalArgumentException(
								"Workbench menu item group is not built in or declared in " + MENU_GROUPS_KEY + ": "
										+ value.trim());
					}
					break;
				case "label":
					if (value.isBlank()) {
						throw new IllegalArgumentException(key + " must not be blank");
					}
					break;
				case "icon":
					break;
				default:
					throw new IllegalArgumentException("Unknown Workbench menu item property: " + key);
				}
				continue;
			}
			if (key.startsWith("menu.group.")) {
				String[] parts = key.substring("menu.group.".length()).split("\\.", 2);
				if (parts.length != 2 || !knownGroupIds.contains(parts[0])) {
					throw new IllegalArgumentException("Unknown or undeclared Workbench property: " + key);
				}
				switch (parts[1]) {
				case "visible":
					parseBoolean(values, key, false);
					break;
				case "order":
					parseInteger(values, key, 0);
					break;
				case "label":
					if (value.isBlank()) {
						throw new IllegalArgumentException(key + " must not be blank");
					}
					break;
				case "icon":
					break;
				default:
					throw new IllegalArgumentException("Unknown Workbench menu group property: " + key);
				}
				continue;
			}
			if (key.startsWith("page.")) {
				String[] parts = key.substring("page.".length()).split("\\.", 2);
				if (parts.length != 2 || !"enabled".equals(parts[1]) || !declaredIds.contains(parts[0])) {
					throw new IllegalArgumentException("Unknown or undeclared Workbench property: " + key);
				}
				parseBoolean(values, key, true);
				continue;
			}
			if (key.startsWith("query.feature.")) {
				String[] parts = key.substring("query.feature.".length()).split("\\.", 2);
				if (parts.length != 2 || !"enabled".equals(parts[1]) || !featureIds.contains(parts[0])) {
					throw new IllegalArgumentException("Unknown or undeclared Workbench property: " + key);
				}
				parseBoolean(values, key, true);
				continue;
			}
			throw new IllegalArgumentException("Unknown Workbench property: " + key);
		}
	}

	private static Map<String, List<String>> collectCustomRoutes(Properties values, Set<String> declaredIds) {
		Map<String, List<String>> routes = new LinkedHashMap<>();
		for (String id : declaredIds) {
			if (BUILT_IN_IDS.contains(id)) {
				continue;
			}
			String href = property(values, "menu.item." + id + ".href", defaultCustomHref(id)).trim();
			String route = property(values, "menu.item." + id + ".route", defaultCustomRoute(href)).trim();
			if (!route.isEmpty()) {
				validateRoute(id, route);
				String routeKey = normalizeRoutePath(route);
				routes.computeIfAbsent(routeKey, ignored -> new ArrayList<>()).add(id);
			}
		}
		return routes;
	}

	private static List<String> parseDeclaredIds(Properties values, String key) {
		List<String> declared = parseList(values.getProperty(key, ""), key);
		assertUnique(declared, key);
		for (String id : declared) {
			validateId(id, key);
		}
		return declared;
	}

	private static void assertUnique(List<String> values, String key) {
		if (new HashSet<>(values).size() != values.size()) {
			throw new IllegalArgumentException(key + " contains duplicate IDs");
		}
	}

	private static Map<String, PageDefinition> builtInPages() {
		// Group ids are configuration contracts: labels, membership and order change, ids never do.
		Map<String, PageDefinition> pages = new LinkedHashMap<>();
		addPage(pages, "query", "explore", "query", "query", "Query", "query");
		addPage(pages, "saved-queries", "explore", "saved-queries", "saved-queries", "Saved queries", "saved");
		addPage(pages, "explore", "explore", "explore", "explore", "Explore", "explore");
		addPage(pages, "summary", "explore", "summary", "summary", "Summary", "summary");
		addPage(pages, "namespaces", "explore", "namespaces", "namespaces", "Namespaces", "namespaces");
		addPage(pages, "contexts", "explore", "contexts", "contexts", "Graphs", "contexts");
		addPage(pages, "types", "explore", "types", "types", "Types", "types");
		addPage(pages, "add", "modify", "add", "add", "Add RDF", "add");
		addPage(pages, "export", "modify", "export", "export", "Export", "export");
		addPage(pages, "update", "modify", "update", "update", "SPARQL Update", "update");
		addPage(pages, "remove", "modify", "remove", "remove", "Remove", "remove");
		addPage(pages, "clear", "modify", "clear", "clear", "Clear", "clear");
		addPage(pages, "repositories", "repositories", "repositories", "/NONE/repositories", "Repositories",
				"repository");
		addPage(pages, "create", "repositories", "create", "create", "Create repository", "create");
		addPage(pages, "delete", "repositories", "delete", "delete", "Delete repository", "delete");
		addPage(pages, "server", "repositories", "server", "/NONE/server", "Connection", "server");
		addPage(pages, "information", "system", "information", "information", "Information", "information");
		return Collections.unmodifiableMap(pages);
	}

	private static Map<String, PageGroupDefinition> builtInGroups() {
		Map<String, PageGroupDefinition> groups = new LinkedHashMap<>();
		groups.put("explore", new PageGroupDefinition("Repository", "explore"));
		groups.put("modify", new PageGroupDefinition("Data", "modify"));
		groups.put("repositories", new PageGroupDefinition("Server", "repository"));
		groups.put("system", new PageGroupDefinition("System", "system"));
		// Declared for administrator configurations; it has no default items and is therefore not rendered.
		groups.put("server", new PageGroupDefinition("Connection", "server"));
		return groups;
	}

